public class LoginServletInseguro extends HttpServlet {
  @Override
  protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    String username = req.getParameter("username");
    String password = req.getParameter("password");

    try {
      Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "app");
      Statement stmt = conn.createStatement();

      // vulnerável: concatenação direta de entrada do usuário permite SQL Injection
      String sql = "SELECT id FROM users WHERE username = '" + username + "' AND password = '" + password + "'";
      ResultSet rs = stmt.executeQuery(sql);

      if (rs.next()) {
        resp.getWriter().println("Login OK");
      } else {
        resp.getWriter().println("Credenciais inválidas");
      }

      // Também há má gestão de recursos: rs/stmt/conn não são fechados
    } catch (SQLException e) {
      resp.getWriter().println("Erro interno");
    }
  }
}

