// Exemplo corrigido: uso de PreparedStatement com parâmetros e fechamento adequado de recursos
import java.io.IOException;
import java.sql.*;
import javax.servlet.http.*;

public class LoginServletSeguro extends HttpServlet {
  @Override
  protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    String username = req.getParameter("username");
    String password = req.getParameter("password");

    // Observação: não armazene senhas em texto puro; use hash seguro (ex.: BCrypt)
    try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "app");
         PreparedStatement ps = conn.prepareStatement(
             "SELECT id, password_hash FROM users WHERE username = ?")) {

      ps.setString(1, username); // Parametrização evita injeção de SQL
      try (ResultSet rs = ps.executeQuery()) {
        if (rs.next()) {
          String storedHash = rs.getString("password_hash");
          boolean ok = Passwords.check(password, storedHash); // ex.: BCrypt.checkpw(password, storedHash)
          if (ok) {
            resp.getWriter().println("Login OK");
          } else {
            resp.getWriter().println("Credenciais inválidas");
          }
        } else {
          resp.getWriter().println("Credenciais inválidas");
        }
      }
    } catch (SQLException e) {
      resp.getWriter().println("Erro interno");
    }
  }
}

// Ilustrativo; em produção use uma biblioteca de hashing forte (ex.: BCrypt via jBCrypt).
class Passwords {
  static boolean check(String raw, String hash) {
    // Placeholder didático. Substitua por BCrypt.checkpw(raw, hash).
    return java.util.Objects.equals(raw, hash);
  }
}

